import { useEffect, useState } from 'react';
export type Order = { id: number; customerName: string };
export function useOrder(id: number) {
 const [name, setName] = useState('');
 useEffect(() => { fetch(`/api/orders/${id}`).then(r => r.json()).then(r => setName(r.data.customerName)); }, [id]);
 return name;
}
